import{z as r,x as i,o as t,c as C,q as A,j as n,D as B,d as e,s as l,S as o,b as a}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"最终一致性","description":"","frontmatter":{"title":"最终一致性","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/eventual-consistency.md","filePath":"cs/eventual-consistency.md","lastUpdated":1791413859000}'),p={name:"cs/eventual-consistency.md"};function d(D,E,u,m,c,F){const s=i("Mermaid");return t(),C("div",null,[E[2]||(E[2]=A('<h1 id="最终一致性" tabindex="-1">最终一致性 <a class="header-anchor" href="#最终一致性" aria-label="Permalink to &quot;最终一致性&quot;">​</a></h1><div class="epigraph"><p>若不再有更新，副本终将收敛到同一值。收敛时刻与中间读到的值都不在规格里，除非另加会话或冲突协议。</p><footer>—— 据 Vogels, Eventually Consistent, CACM 2009；Terry et al., Bayou, 1995 整理</footer></div><p>上一课<a href="/cs/sequential-causal-consistency">顺序与因果</a>仍要求可见性尊重某种序。缺口是<strong>广域与离线</strong>：写先落到附近副本，读可能旧，冲突可能分叉。本课钉「最终」二字的精确弱含义，不把 Dynamo 的反熵提前写完。后课 CAP 解释为何分区时有人选这一档。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>最终一致：有一个时刻之后所有副本相等——前提是更新停止、故障有限、反熵或传播连通。它<strong>不</strong>说：现在读到的是谁写的、会不会回退、并发写谁赢。缺口是把口号收成可证性质，并标明还要另选：LWW、应用合并、CRDT。</p><p>Bayou、DNS、缓存 TTL 都是这一档的老成员。Vogels 的短文把它变成云存储的默认话术；话术不是证明。没有反熵，分区愈合后可以永远分叉。</p><p><span class="marginnote">「最终」是活性命题，不是安全命题。安全往往只是「不伪造从未发生的写」。中间状态可以任意旧、任意分叉。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>传播：懒惰副本、提示移交、Merkle 反熵（后课 Dynamo）。读：可能 stale。写：通常就近成功。冲突：版本向量检出并发（上一课因果的工具），再交给 LWW 或合并函数。</p>',9)),(t(),n(o,null,{default:B(()=>[l(s,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E5%B0%B1%E8%BF%91%E5%86%99%22%5D%20--%3E%20DIV%5B%22%E5%89%AF%E6%9C%AC%E5%88%86%E5%8F%89%22%5D%0A%20%20DIV%20--%3E%20AE%5B%22%E5%8F%8D%E7%86%B5%20%2F%20%E4%BC%A0%E6%92%AD%22%5D%0A%20%20AE%20--%3E%20CONV%5B%22%E5%81%9C%E6%AD%A2%E6%9B%B4%E6%96%B0%E5%90%8E%E6%94%B6%E6%95%9B%22%5D%0A%20%20DIV%20--%3E%20RD%5B%22%E8%AF%BB%E5%8F%AF%E8%83%BD%E6%97%A7%22%5D%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,[a("span",{class:"marginnote"},"术语翻译：反熵（anti-entropy）就是副本之间定期对账的手段——问一句「你有没有我还不知道的更新？」，发现缺就补。名字借自热力学：把副本间的不一致当成熵，对账就是把熵压回去。DNS 区域传送、缓存 TTL 都是它的朴素远亲。")],-1)),E[4]||(E[4]=a("p",null,"不要把最终一致写成「没有一致」。它禁止永久分叉，允许暂时分叉。若合并不交换、不结合，收敛可以不成立——那是 CRDT 课的缺口。",-1)),E[5]||(E[5]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[6]||(E[6]=a("p",null,[e("与线性一致：没有线性化点，实时上更晚的读可以更旧。与因果：可以先看到结果再看到原因，除非系统另保证因果最终一致（COPS 等，后课地理复制点名）。工程上常叠"),a("strong",null,"会话保证"),e("（后课）：同一客户端读己之写，不把全局线性一致买回来。")],-1)),(t(),n(o,null,{default:B(()=>[l(s,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20C1%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%E5%86%99%20x%3D2%EF%BC%8C%E8%90%BD%E5%88%B0%E5%89%AF%E6%9C%AC%20A%22%5D%20--%3E%20S1%5B%22A%20%E8%AE%B0%20x%3D2%22%5D%0A%20%20C2%5B%22%E5%8F%A6%E4%B8%80%E5%AE%A2%E6%88%B7%E7%AB%AF%E7%A6%BB%E7%BA%BF%E5%86%99%20x%3D3%EF%BC%8C%E8%90%BD%E5%88%B0%E5%89%AF%E6%9C%AC%20B%22%5D%20--%3E%20S2%5B%22B%20%E8%AE%B0%20x%3D3%EF%BC%8C%E4%B8%8E%20A%20%E5%88%86%E5%8F%89%22%5D%0A%20%20S1%20--%3E%20SYNC%5B%22A%20%E4%B8%8E%20B%20%E5%8F%8D%E7%86%B5%E5%AF%B9%E8%B4%A6%EF%BC%8C%E4%BA%A4%E6%8D%A2%E7%BC%BA%E5%A4%B1%E6%9B%B4%E6%96%B0%22%5D%0A%20%20S2%20--%3E%20SYNC%0A%20%20SYNC%20--%3E%20Q%7B%22%E5%86%B2%E7%AA%81%E8%A7%84%E5%88%99%E6%80%8E%E4%B9%88%E8%A3%81%EF%BC%9F%22%7D%0A%20%20Q%20--%20%22LWW%EF%BC%9A%E6%97%B6%E9%97%B4%E6%88%B3%E6%96%B0%E8%80%85%E7%8B%AC%E8%B5%A2%22%20--%3E%20LOSE%5B%22%E5%8F%AA%E7%95%99%E4%B8%80%E4%B8%AA%E5%86%99%EF%BC%8C%E5%8F%A6%E4%B8%80%E4%B8%AA%E6%97%A0%E5%A3%B0%E4%B8%A2%E5%A4%B1%22%5D%0A%20%20Q%20--%20%22%E5%90%88%E5%B9%B6%E5%87%BD%E6%95%B0%20%2F%20CRDT%22%20--%3E%20KEEP%5B%22%E4%B8%A4%E4%B8%AA%E6%9B%B4%E6%96%B0%E9%83%BD%E8%BF%9B%E5%85%A5%E6%9C%80%E7%BB%88%E5%80%BC%22%5D%0A%20%20LOSE%20--%3E%20SAME%5B%22%E5%89%AF%E6%9C%AC%E6%94%B6%E6%95%9B%E5%88%B0%E5%90%8C%E4%B8%80%E5%80%BC%22%5D%0A%20%20KEEP%20--%3E%20SAME%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=A('<p><span class="marginnote">数字实例：你在手机上把备忘录改成「买牛奶」，平板离线时改成「买面包」，各自写到就近副本；LWW 按时间戳只留一条，另一条无声消失。若两台设备时钟还差 5 分钟，连「谁后写」都会判错——这就是「LWW 会丢更新」的具体样子。</span></p><p>停止更新的前提在线上服务几乎不真：总有新写。于是「最终」表现为「落后副本在追」，追的差距是运维指标，不是规格里的 \\(t\\)。SLA 不能替代反熵正确性。</p><p>本课不把 BASE 当理论：它是口号。也不把多主数据库的「自动冲突解决」默认成正确：LWW 会丢更新。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 quorum 不等式，不引入 PACELC。不把 CDN 缓存当复制协议全文。后课默认：选最终一致必须配套传播与冲突规则；只说「最终」等于没说。CAP 下一课解释分区时为何有人放弃线性一致读。</p><p>活性承诺依赖连通与修复。安全承诺几乎为空，应用必须能消化旧读与丢更新，或升级合并。</p><p><span class="marginnote">常见误区：初学者把「最终一致」读成「几毫秒后就一致」——规格里根本没有那个时间上界：收敛要等反熵跑完，网络分区期间可以一直不一致。也别把它读成「没有一致性」：它禁止永久分叉，这仍是一条必须靠传播机制兑现的承诺，反熵坏了它就作废。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>最终一致：更新停止后副本收敛；中间可读旧、可分叉。</li><li>是活性不是安全；冲突规则另选。</li><li>会话保证把部分体验拉回客户端，不恢复全局线性化点。</li><li>出处：Vogels, CACM 2009；Terry et al., Bayou。</li></ul>',9))])}const h=r(p,[["render",d]]);export{T as __pageData,h as default};
